    steps: [
      "Whisk the oil and flour together in a heavy pot (cast iron is traditional) over medium heat. Cook, whisking constantly, for 25–35 minutes as the roux darkens from blond to the color of dark chocolate — it will go from smelling like raw flour to nutty and toasted; do not walk away, a scorched roux can't be saved and must be started over.",
      "The moment the roux hits the right color, add the onion, celery, and bell pepper all at once — the drop in temperature stops the cooking and prevents burning. Stir 5 minutes until the vegetables soften slightly.",
      "Stir in the garlic and cook 1 minute, until fragrant.",
      "Add the andouille sausage and cook 5 minutes to render some fat and brown the edges.",
      "Gradually whisk in the chicken stock, a ladle at a time at first to keep the roux smooth, until fully incorporated.",
      "Add the chicken, bay leaves, thyme, cayenne if using, and salt. Bring to a gentle simmer, then partially cover and cook 45 minutes, stirring occasionally.",
      "Stir in the okra if using and simmer another 15 minutes until the chicken is fully tender and the gumbo has thickened slightly.",
      "Remove the bay leaves. Serve over rice, with filé powder passed at the table for anyone who wants to stir it in.",
    ],
    notes:
      "Gumbo is a defining dish of Louisiana Creole and Cajun cooking, blending West African (okra, a thickener and namesake — 'gumbo' likely derives from a West African word for okra), French (the roux), and Native American (filé powder, from ground sassafras leaves) techniques into one pot.",
    sourceName: "Southern Foodways Alliance",
    sourceUrl: "https://www.southernfoodways.org/",
