      "Whisk the flour, cocoa powder, baking soda, and salt in a bowl.",
      "Beat the softened butter and sugar with an electric mixer until light and fluffy, about 3 minutes. Beat in the eggs one at a time, then the oil.",
      "Whisk the buttermilk, vanilla, and food coloring together in a separate small bowl.",
      "Add the flour mixture and buttermilk mixture to the butter mixture alternately, in three additions, beginning and ending with the flour — mixing just until combined each time.",
      "Stir in the vinegar (it reacts with the baking soda for lift).",
      "Divide the batter between the pans and bake 25–30 minutes until a toothpick comes out clean. Cool completely on a rack.",
